def transform(grid):
    # Remove adjacent duplicate rows, then adjacent duplicate column profiles.
    rows = []
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])
    columns = []
    for c in range(len(rows[0])):
        profile = tuple(row[c] for row in rows)
        if not columns or profile != columns[-1][1]:
            columns.append((c, profile))
    return [[row[c] for c, _ in columns] for row in rows]
